create extension if not exists pgcrypto;
create type public.app_role as enum ('ADMIN','CONTENT_MANAGER','WAREHOUSE_MANAGER');
create type public.inventory_movement_type as enum ('stock_in','sale','return','correction','damaged','reserved');
create type public.order_status as enum ('pending','confirmed','processing','shipped','delivered','cancelled','returned');
create type public.notification_type as enum ('LOW_STOCK','NEW_ORDER','ORDER_STATUS','AI_GENERATION','SYSTEM');
create table public.roles(id uuid primary key default gen_random_uuid(),name public.app_role unique not null,created_at timestamptz not null default now());
insert into public.roles(name) values('ADMIN'),('CONTENT_MANAGER'),('WAREHOUSE_MANAGER') on conflict do nothing;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,role public.app_role not null default 'WAREHOUSE_MANAGER',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(),name text unique not null,slug text unique not null,description text,created_at timestamptz not null default now());
create table public.products(id uuid primary key default gen_random_uuid(),category_id uuid references public.categories(id) on delete set null,name text not null,slug text unique not null,description text,seo_title_ru text,seo_title_tg text,description_ru text,description_tg text,short_description text,characteristics jsonb not null default '{}',laklak_tags text[] not null default '{}',keywords text[] not null default '{}',hashtags text[] not null default '{}',active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.product_variants(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,sku text unique not null,color text,material text,size text,cost_price numeric(12,2) not null check(cost_price>=0),selling_price numeric(12,2) not null check(selling_price>=0),quantity integer not null default 0 check(quantity>=0),minimum_quantity integer not null default 0 check(minimum_quantity>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index product_variants_product_idx on public.product_variants(product_id);create index product_variants_stock_idx on public.product_variants(quantity,minimum_quantity);
create table public.product_images(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,variant_id uuid references public.product_variants(id) on delete cascade,storage_path text not null,kind text not null check(kind in('original','generated')),alt_text text,sort_order integer not null default 0,created_at timestamptz not null default now());
create table public.inventory_movements(id uuid primary key default gen_random_uuid(),variant_id uuid not null references public.product_variants(id) on delete restrict,type public.inventory_movement_type not null,quantity integer not null check(quantity>0),reference_id uuid,note text,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create index inventory_movements_variant_idx on public.inventory_movements(variant_id,created_at desc);
create table public.customers(id uuid primary key default gen_random_uuid(),full_name text,phone text,email text,notes text,created_at timestamptz not null default now());
create table public.orders(id uuid primary key default gen_random_uuid(),customer_id uuid references public.customers(id) on delete set null,status public.order_status not null default 'pending',total numeric(12,2) not null default 0 check(total>=0),created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index orders_status_created_idx on public.orders(status,created_at desc);
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,variant_id uuid not null references public.product_variants(id) on delete restrict,quantity integer not null check(quantity>0),unit_price numeric(12,2) not null check(unit_price>=0),cost_price numeric(12,2) not null check(cost_price>=0),line_total numeric(12,2) generated always as(quantity*unit_price) stored);
create table public.financial_transactions(id uuid primary key default gen_random_uuid(),order_id uuid references public.orders(id) on delete set null,type text not null check(type in('sale','cost','refund','adjustment')),amount numeric(12,2) not null,note text,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create table public.ai_generations(id uuid primary key default gen_random_uuid(),product_id uuid references public.products(id) on delete set null,source_image_path text,prompt_version text not null,provider text not null,model text not null,status text not null check(status in('pending','completed','failed','approved')),output jsonb,error_message text,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,type public.notification_type not null,title text not null,message text not null,read_at timestamptz,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create index notifications_user_created_idx on public.notifications(user_id,created_at desc);
create table public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references auth.users(id) on delete set null,action text not null,entity_type text not null,entity_id uuid,before_data jsonb,after_data jsonb,created_at timestamptz not null default now());
insert into public.categories(name,slug) values('Scarves','scarves'),('Hijabs','hijabs'),('Accessories','accessories'),('Bags','bags') on conflict do nothing;
